"""B0005 decisions from inspected primary sections and deposited abstracts."""
import json
import ledger as L
from review_batch_0001 import evidence

def main():
 base=L.ROOT/'assets/research-20261105'
 specs={
 '10.1039/c0jm02754e':('metadata_screened','uncertain',[], 'Publisher abstract describes nanoparticle chains on linear DNA, not an identified origami object. Publisher labels article Highlight; full body still needed for final disposition.', 'Inspect full body and referenced chain designs; distinguish DNA templating from origami.'),
 '10.1073/pnas.1017999108':('metadata_screened','uncertain',[], 'Deposited abstract reports a 100-residue RNA square assembled from four copies each of 10- and 15-base oligos; this described object is RNA, but full-article screening remains open.', 'Inspect full article before final DNA-origami exclusion; retain RNA design as context.'),
 '10.1088/0957-4484/22/27/275301':('metadata_screened','uncertain',[], 'Crossref bibliographic record has no abstract. Title alone does not establish design reuse or completeness.', 'Acquire primary abstract, article and nanoribbon sources.'),
 '10.1093/nar/gkr1173':('fulltext_reviewed','design_bearing',['new_design','modified_design','reused_design'], 'Results report newly built A- and S-shaped multilayer objects and four experimentally tested honeycomb 32-helix bundles with crossover spacings21,42,63,84bp. Earlier square-lattice blocks, rectangle and tensegrity are analyzed computationally; distinguish reused models from newly built objects.', 'Inspect Supplementary Figures S18–23, source diagrams and sequence files; independently establish A/S lattice and exact variant composition.'),
 '10.1098/rsif.2010.0729':('fulltext_reviewed','background_or_review',[], 'Sections2–6 describe seesaw strand-displacement gate complexes and simulated circuit behavior. Discussion cites scaffolded origami as inspiration for robustness, rather than presenting an origami gate carrier.', 'Audit complete body and supplement before final design-census exclusion; record cited origami papers as discovery leads.'),
 '10.1038/nmeth.1570':('design_sources_reviewed','design_bearing',['reused_design'], 'SI methods report experimental thermal/nuclease tests of purified18-,24-,32-helix bundles. Contents identify separate robot and tetrameric60-helix layouts. A protocol title does not make this background-only literature.', 'Inspect Figs1–5 routing and obtain source files; resolve new versus previously reported geometries, controls and scaffold sequences.'),
 '10.1039/c0sm01259a':('metadata_screened','design_bearing',['modified_design'], 'Publisher abstract reports tested edge-staple omissions, T-bumpers and varied single-strand linkers on notched origami, with AFM characterization of oligomers. Main text and supplement remain uninspected.', 'Acquire9.1MB SI and primary methods; reconcile edge deletions, linkers and parent geometry.'),
 '10.1098/rsfs.2011.0040':('metadata_screened','background_or_review',[], 'Deposited abstract explicitly describes a review of nucleic-acid assembly strategies and nanomedicine devices; no new origami object is established by this abstract.', 'Inspect full review and extract cited original design publications; no final catalog exclusion yet.'),
 '10.1109/nems.2011.6017328':('metadata_screened','uncertain',[], 'Crossref identifies a proceedings article. Local publisher fetch returned zero bytes and is not usable evidence of experimental design; full paper remains to be acquired.', 'Acquire proceedings paper and reconcile possible journal counterpart without merging by title.'),
 '10.1116/1.3646900':('metadata_screened','design_bearing',['reused_design'], 'Deposited abstract describes experimentally assembling DNA-origami scaffolds in nanoimprint-patterned surface areas. No origami source layout is provided by this abstract.', 'Inspect primary methods and source of reused origami; separate surface pattern dimensions from origami routing.')}
 for doi,(stage,rel,con,note,q) in specs.items():
  r=next(r for r in L.read('publication_reviews') if r['doi']==doi)
  if r['run_id']!='bootstrap-20261105':continue
  file=base/(doi.replace('/','_')+'.json');url='https://api.crossref.org/works/'+doi;loc='Deposited title/type and abstract when present'
  if doi=='10.1093/nar/gkr1173':file=L.ROOT/'assets/sources/PMC3326316.xml';url='https://pmc.ncbi.nlm.nih.gov/articles/PMC3326316/';loc='Abstract; Methods; complete Results and Discussion including Figs2–4'
  if doi=='10.1098/rsif.2010.0729':file=L.ROOT/'assets/sources/pre2020-expansion/PMC3140723.xml';url='https://pmc.ncbi.nlm.nih.gov/articles/PMC3140723/';loc='Abstract and opening passages of body sections1–7, especially gate motif and Discussion'
  if doi=='10.1038/nmeth.1570':file=base/'castro-primer-si.pdf';url='https://www.dna.caltech.edu/~pwkr/dna-nanotech-reviews/2011-dietz-dna-origami-primer-supp.pdf';loc='PDF pp.1,22,30: contents; Note1; experimental stability methods'
  if doi=='10.1039/c0jm02754e':file=base/'b0005-rsc-web-response.json';url='https://pubs.rsc.org/en/content/articlelanding/2011/jm/c0jm02754e';loc='Saved web-tool publisher response abstract lines54–56 and article type/date'
  if doi=='10.1039/c0sm01259a':file=base/'b0005-alignment-web-response.json';url='https://pubs.rsc.org/en/content/articlelanding/2011/sm/c0sm01259a';loc='Saved publisher search-result abstract; direct open returned403'
  r.update(review_stage=stage,relevance=rel,design_contributions=con,catalog_eligibility='unresolved',evidence=[evidence(file,url,loc)],rationale=note,unresolved_questions=[q],access='partial',reviewer='Codex source section / abstract inspection',run_id='B0005',date=L.DATE)
  if doi=='10.1109/nems.2011.6017328':r['publication_type']=['conference_proceedings_article']
  L.upsert('publication_reviews',r,'B0005 balanced rotation; evidence depth and open checks explicit')
 r=next(r for r in L.read('publication_reviews') if r['doi']=='10.1021/ac402118a')
 if r['run_id']=='bootstrap-20261105':
  acs=next(a for a in json.loads((L.ROOT/'acs_acquisition.json').read_text())['records'] if a['doi']==r['doi']);f=next(f for f in acs['files'] if f.get('local_file','').endswith('.pdf'))
  ev=[evidence(base/'crooks-origami-paper-devices.pdf','https://rcrooks.cm.utexas.edu/research/resources/Publications/rmc250.pdf','PDF pp.2,6: all oligo materials, wax-printed paper fabrication and Conclusions'),evidence(L.ROOT/'assets'/f['local_file'],f['url'],'PDF p.3 FigS2 and paper-folding assay caption')]
  r.update(review_stage='fulltext_reviewed',relevance='not_origami',catalog_eligibility='excluded',design_contributions=[],evidence=ev,rationale='Origami refers to centimetre-scale wax-printed folded paper layers. DNA is a strand-displacement analyte/probe assay; the inspected materials, fabrication and conclusions establish no molecular DNA-origami scaffold.',unresolved_questions=[],access='partial',reviewer='Codex primary source inspection and same-agent second-pass exclusion audit',run_id='B0005',date=L.DATE)
  L.upsert('publication_reviews',r,'Exclude paper-folding false positive after main article and SI second pass')
 # Named design evidence from actual primary experimental descriptions, no molecular authoring.
 p=next(r for r in L.read('publication_reviews') if r['doi']=='10.1093/nar/gkr1173');ev=p['evidence'][0]
 for did,names,lattice,composition in [('RDE0006',['A-shaped multilayer origami','S-shaped multilayer origami'],'unresolved','Two distinct reported geometries; S curvature uses balanced insertions/deletions. Separate routing/source verification required for each.'),('RDE0007',['32-helix bundle crossover-density series'],'honeycomb_explicit_primary_results','Four experimentally built variants with crossover spacings21,42,63,84bp; do not collapse into a single sequence set.')]:
  if any(d['design_id']==did for d in L.read('design_evidence')):continue
  L.upsert('design_evidence',dict(design_id=did,publication_keys=[p['registry_key']],named_objects=names,variant_links=[],relationships=[],lattice_decision=lattice,catalog_eligibility='unresolved',evidence=[ev],source_files=[ev],core_variant_composition=composition,source_completeness='not_verified',outstanding_checks=p['unresolved_questions'],legacy_record={},review_run='B0005',date=L.DATE),'Capture newly inspected design groups; no scope promotion')
 b=next(b for b in L.read('batches') if b['batch_id']=='B0005')
 b.update(status='completed',completed_actions=['Inspected15 ACS supplements;14 decisions in review_batch_0005.py plus paper-folding exclusion checked against primary main article.','Screened10 balanced rotating records using primary XML, author-hosted SI and deposited/publisher abstracts; missing bodies explicitly retained.','Recorded two provisional design groups from CanDo validation experiments.','Empty HTTP response found and marked failed; downloader rejects empty bodies and regression test added.'],exclusion_audit={'sample':['10.1021/ac402118a'],'reason':'All one final exclusion in B0005; same-agent second pass main PDFpp2,6 and SI p3 confirms paper substrate and probe chemistry. Not independent review.'},after_counts=L.counts(),validation=[L.validate()],unresolved_keys=[r['registry_key'] for r in L.read('publication_reviews') if r['registry_key'] in b['input_keys'] and r['unresolved_questions']],next_queue=['Select B0006 balanced queue','Acquire CanDo gkr1173 SI and inspect source diagrams','Acquire alignment SI and reconcile origami edge variants','Continue FNANO2017 full program and author/citation routes'])
 L.upsert('batches',b,'Complete25 first-pass screens with unresolved source work explicit')
 print(L.validate())
if __name__=='__main__':main()
